  div#wrapper {
    width: 100%;
    box-sizing: border-box;
    padding: 0 15px;
  }
  body.smallhead div#wrapper {
    width: 100%;
    box-sizing: border-box;
    padding: 15px;
  }
  div#smallhead #smallhead-inner {
    width: 100%;
    box-sizing: border-box;
    padding-left: 15px;
    padding-right: 15px;
  }
  div#bighead {
    width: 100%;
    box-sizing: border-box;
  }
  div#primary {
    width: calc(100% - 315px); /* 280px sidebar + 35px margin */
  }
}

