}

.pl-v /* variable */,
.pl-smw /* sublimelinter.mark.warning */ {
  color: var(--color-code-value);
}

.pl-bu /* invalid.broken, invalid.deprecated, invalid.unimplemented, message.error, brackethighlighter.unmatched, sublimelinter.mark.error */ {
  color: #b31d28;
}

.pl-ii /* invalid.illegal */ {
  color: #fafbfc;
  background-color: #b31d28;
}

.pl-c2 /* carriage-return */ {
  color: #fafbfc;
  background-color: #d73a49;
}

.pl-c2::before /* carriage-return */ {
  content: "^M";
}

.pl-sr .pl-cce /* string.regexp constant.character.escape */ {
  font-weight: bold;
  color: #22863a;
}

.pl-ml /* markup.list */ {
  color: #735c0f;
}

.pl-mh /* markup.heading */,
.pl-mh .pl-en /* markup.heading entity.name */,
.pl-ms /* meta.separator */ {
  font-weight: bold;
  color: #005cc5;
}

.pl-mi /* markup.italic */ {
  font-style: italic;
  color: #24292e;
}

.pl-mb /* markup.bold */ {
  font-weight: bold;
  color: #24292e;
}

.pl-md /* markup.deleted, meta.diff.header.from-file, punctuation.definition.deleted */ {
  color: #b31d28;
  background-color: #ffeef0;
}

.pl-mi1 /* markup.inserted, meta.diff.header.to-file, punctuation.definition.inserted */ {
  color: #22863a;
  background-color: #f0fff4;
}

.pl-mc /* markup.changed, punctuation.definition.changed */ {
  color: #e36209;
  background-color: #ffebda;
}

.pl-mi2 /* markup.ignored, markup.untracked */ {
  color: #f6f8fa;
  background-color: #005cc5;
}

.pl-mdr /* meta.diff.range */ {
  font-weight: bold;
  color: #6f42c1;
}

.pl-ba /* brackethighlighter.tag, brackethighlighter.curly, brackethighlighter.round, brackethighlighter.square, brackethighlighter.angle, brackethighlighter.quote */ {
  color: #586069;
}

.pl-sg /* sublimelinter.gutter-mark */ {
  color: #959da5;
}

.pl-corl /* constant.other.reference.link, string.other.link */ {
  text-decoration: underline;
  color: #032f62;
}

/*
 * Pygments syntax highlighting (codehilite)
 * Maps Pygments token classes to existing CSS custom properties
 * for automatic light/dark theme support.
 */
.codehilite {
  background: var(--color-code-bg);
  padding: 0.5em;
  overflow-x: auto;
  border-radius: 6px;
  border: 1px solid var(--color-border);
  margin: 1em 0;
}
.codehilite pre {
  margin: 0;
  line-height: 1.45;
}
.codehilite code {
  background: none;
  padding: 0;
  border: none;
}
/* Comments */
.codehilite .c,
.codehilite .ch,
.codehilite .cm,
.codehilite .cpf,
.codehilite .c1,
.codehilite .cs { color: var(--color-code-comment); font-style: italic; }
.codehilite .cp { color: var(--color-code-comment); font-weight: bold; font-style: italic; }
/* Keywords */
.codehilite .k,
.codehilite .kd,
.codehilite .kn,
.codehilite .kr,
.codehilite .kt { color: var(--color-code-keyword); }
.codehilite .kc,
.codehilite .kp { color: var(--color-code-constant); }
/* Strings */
.codehilite .s,
.codehilite .sa,
.codehilite .sb,
.codehilite .sc,
.codehilite .dl,
.codehilite .sd,
.codehilite .s2,
.codehilite .se,
.codehilite .sh,
.codehilite .si,
.codehilite .sx,
.codehilite .sr,
.codehilite .s1,
.codehilite .ss { color: var(--color-code-string); }
/* Numbers/literals */
.codehilite .m,
.codehilite .mb,
.codehilite .mf,
.codehilite .mh,
.codehilite .mi,
.codehilite .mo,
.codehilite .il { color: var(--color-code-constant); }
/* Names */
.codehilite .n,
.codehilite .na,
.codehilite .nb,
.codehilite .ni,
.codehilite .nl,
.codehilite .nn,
.codehilite .nx,
.codehilite .py,
.codehilite .nv,
.codehilite .bp,
.codehilite .vc,
.codehilite .vg,
.codehilite .vi,
.codehilite .vm { color: var(--color-code-variable); }
/* Functions/entities */
.codehilite .nf,
.codehilite .fm,
.codehilite .nc,
.codehilite .nd,
.codehilite .ne { color: var(--color-code-entity); }
/* Tags (HTML/XML) */
.codehilite .nt { color: var(--color-code-tag); }
/* Constants */
.codehilite .no { color: var(--color-code-constant); }
/* Operators */
.codehilite .o,
.codehilite .ow { color: var(--color-code-keyword); font-weight: bold; }
/* Punctuation */
.codehilite .p,
.codehilite .pm { color: var(--color-code-variable); }
/* Generic */
.codehilite .gd { color: var(--color-code-keyword); }
.codehilite .gi { color: var(--color-code-tag); }
.codehilite .gh,
.codehilite .gu { color: var(--color-code-constant); font-weight: bold; }
.codehilite .ge { font-style: italic; }
.codehilite .gs { font-weight: bold; }
.codehilite .err { color: var(--color-code-keyword); }
/* Values/decorators */
.codehilite .l,
.codehilite .ld { color: var(--color-code-value); }
/* Whitespace */
.codehilite .w { color: var(--color-code-comment); }

/* Custom page templates */
.entry-wide div#primary {
  width: auto;
  margin: 0 1em;
  float: none;
  max-width: 98%;
}
.entry-wide div#wrapper {
  overflow: visible;
}

body.homepage .hide-on-homepage {
  display: none;
}

#h1-nav-wrapper {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: flex-start;
}
#h1-nav-wrapper h1 {
  margin-right: 3em;
}
#h1-nav-wrapper ul {
  list-style-type: none;
  margin: 0;
  padding: 0 1em 0 0;
  display: flex;
  gap: 10px;
  align-items: center;
  padding-bottom: 0.5em;
}
#h1-nav-wrapper li {
  display: inline;
  padding-right: 0.5em;
}
#h1-nav-wrapper li a {
  border-bottom: none;
  font-weight: bold;
}

/* Tag styles */
a.item-tag {
  display: inline-block;
  background-color: var(--color-tag-bg);
  padding: 4px 10px;
  border-radius: 5px;
  border: 1px solid var(--color-tag-border);
  border-bottom: 1px solid var(--color-tag-border);
  text-decoration: none;
  color: var(--color-tag-text);
  margin-right: 0.3em;
  margin-bottom: 0.5em;
}
a.item-tag:hover {
  background-color: var(--color-purple-hover);
}
#bighead a.item-tag {
  padding: 0px 8px;
}
.item-tag span {
  color: var(--color-tag-count);
  font-size: 0.6em;
  vertical-align: middle;
}

/* Nested lists - used on /2020/ page

/* Inline #3 | http://0.0.0.0:8033/2019/ */

div.entry li li {
  margin-bottom: 0.2em;
}
div.entry ul ul {
  margin-bottom: 0;
}
div.entry li li:first-of-type {
  margin-top: 0.2em;
}

.card-container img {
  display: block;
  max-width: 100%;
}

a:link.photoswipe-img,
a:visited.photoswipe-img,
a:hover.photoswipe-img,
a:focus.photoswipe-img,
a:active.photoswipe-img {
  border: none;
}

div.ea-placement a:link {
  border-bottom: none;
}

.recent-articles {
  margin-top: 1em;
}
.recent-articles li {
  list-style-type: square;
  margin-left: 1em;
  margin-bottom: 0.1em;
}

.tag-description {
  margin-bottom: 1em;
}

/* Theme toggle button */
#theme-toggle {
  background: none;
  border: none;
  cursor: pointer;
  padding: 0 0.5em;
  color: white;
  opacity: 0.8;
  transition: opacity 0.2s;
  vertical-align: middle;
  display: inline-flex;
  align-items: center;
}
#theme-toggle:hover {
  opacity: 1;
}
#theme-toggle svg {
  width: 18px;
  height: 18px;
  fill: currentColor;
}

/* Edit page link */
body div .edit-page-link {
  margin-top: 0.5em;
}
a.edit-link {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  font-size: 0.8em;
  padding: 3px 8px;
  background-color: var(--color-purple-light);
  border: 1px solid var(--color-purple-border);
  border-radius: 4px;
  color: var(--color-text);
  text-decoration: none;
}
a.edit-link:hover {
  background-color: var(--color-purple-hover);
}
a.edit-link svg {
  flex-shrink: 0;
}
a.random-post-link {
  float: right;
  display: inline-flex;
  align-items: center;
  gap: 4px;
  font-size: 0.85em;
  padding: 4px 10px;
  margin-top: 0.3em;
  margin-right: 0.75em;
  background-color: var(--color-purple-light);
  border: 1px solid var(--color-purple-border);
  border-radius: 4px;
  color: var(--color-text);
  text-decoration: none;
}
a.random-post-link:hover {
  background-color: var(--color-purple-hover);
  border-bottom: 1px solid var(--color-purple-border);
}
a.random-post-link svg {
  flex-shrink: 0;
}
a.random-tag-nav {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  font-size: 0.85em;
  padding: 4px 10px;
  margin-right: 1em;
  background-color: rgba(255, 255, 255, 0.2);
  border: 1px solid rgba(255, 255, 255, 0.4);
  border-radius: 4px;
  color: #fff;
  text-decoration: none;
}
a.random-tag-nav:hover {
  background-color: rgba(255, 255, 255, 0.3);
  border-bottom: 1px solid rgba(255, 255, 255, 0.4);
}
a.random-tag-nav svg {
  flex-shrink: 0;
}

/* ── Beat component ─────────────────────────────────────
   Two-row slim timeline entry. Row 1: label + title + optional
   commit message, wrapping to additional lines as needed.
   Row 2: muted metadata (date, context, tags).
   ──────────────────────────────────────────────────── */

div.beat {
  font-size: 0.875rem;
  line-height: 1.4;
}

.beat-row1 {
  /* Inline flow so the label sits next to the title text and the
     title wraps naturally around it on narrow viewports. */
}

.beat-row2 {
  margin-top: 2px;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.beat-label {
  display: inline-flex;
  align-items: center;
  flex-shrink: 0;
  margin-right: 5px;
  padding: 1px 7px;
  border-radius: 3px;
  font-size: 0.68rem;
  font-weight: 700;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  position: relative;
  top: -1px;
}

a.beat-label:link,
a.beat-label:visited,
a.beat-label:focus,
a.beat-label:hover,
a.beat-label:active {
  text-decoration: none;
  border-bottom-style: solid;
}

.beat-title {
  font-weight: 600;
}

.beat-title a {
  font-weight: 600;
}

.beat-commit {
  color: var(--color-text-muted);
  font-size: 0.9em;
  overflow: hidden;
  text-overflow: ellipsis;
  flex-shrink: 2;
  min-width: 0;
}

.beat-note {
  margin-top: 8px;
  margin-bottom: 8px;
  font-size: 0.9rem;
  white-space: normal;
}

.beat-note img,
.beat-note video {
  max-width: 100%;
  height: auto;
}

.beat-note p {
  margin-bottom: 0.8em;
}

.beat-note p:last-child {
  margin-bottom: 0;
}

.beat-meta {
  font-size: 0.8em;
  color: var(--color-text-muted);
}

.beat-meta a {
  color: var(--color-text-muted);
  border-color: transparent;
}

.beat-meta a:hover {
  color: var(--color-text);
}

/* ── Beat image thumbnail ── */

.beat-has-image::after {
  content: "";
  display: block;
  clear: both;
}

.beat-image-link,
.beat-image-link:link,
.beat-image-link:visited,
.beat-image-link:link:hover,
.beat-image-link:link:focus,
.beat-image-link:link:active {
  float: right;
  margin: 0 0 8px 12px;
  border: none;
}

.beat-image {
  width: 90px;
  height: 60px;
  object-fit: cover;
  border-radius: 4px;
  border: none;
  outline: none;
  display: block;
}

.beat-note blockquote code,
.beat-note pre,
.beat-note pre code {
  word-break: break-word;
  overflow-wrap: anywhere;
}

body.sighting-detail-page div#wrapper {
  overflow: visible;
}

body.sighting-detail-page div#primary {
  float: none;
  width: auto;
  max-width: 920px;
  margin: 0 auto;
}

body.sighting-detail-page div#secondary {
  float: none;
  width: 560px;
  max-width: 100%;
  margin: 1.5em auto 0;
}

body.sighting-detail-page .sighting-detail-gallery {
  --max-row-height: 420px;
  --single-image-max-height: 720px;
  margin-top: 10px;
}

/* ── Label colours by beat type ── */

.beat-label.release {
  background: var(--color-purple-light);
  color: var(--color-purple-accent);
  border: 1px solid #8a55a8;
}

.beat-label.til {
  background: #e6f9f0;
  color: #1a7a4a;
  border: 1px solid #a8dfc4;
}

.beat-label.til-update {
  background: #e6f9f0;
  color: #1a7a4a;
  border: 1px solid #a8dfc4;
  padding-right: 0;
  overflow: hidden;
}
.beat-label.til-update .til-update-suffix {
  display: inline-block;
  padding: 0 7px;
  margin-left: 5px;
  background: #c8eedd;
  color: #1a7a4a;
  opacity: 0.75;
  font-weight: 500;
  font-style: italic;
  letter-spacing: 0.02em;
  text-transform: none;
}

.beat-label.research {
  background: #fff8e1;
  color: #8a6200;
  border: 1px solid #f0d080;
}

.beat-label.tool {
  background: #fce8f3;
  color: #9c1f6e;
  border: 1px solid #f0a8d8;
}
.beat-label.museum {
  background: #e0f2f1;
  color: #00695c;
  border: 1px solid #80cbc4;
}
.beat-label.sighting {
  background: #e8f5e9;
  color: #1b5e20;
  border: 1px solid #81c784;
}
.beat-label.comment {
  background: #e3f0fb;
  color: #135a9e;
  border: 1px solid #9cc7ec;
}
.comment-context {
  font-style: italic;
  color: #666;
  font-size: 0.9em;
  margin-bottom: 0.4em;
}
.comment-source-bar {
  margin: 0 0 0.6em 0;
  font-size: 0.85em;
}
.comment-source-bar .beat-label {
  margin-right: 6px;
}
.comment-source-bar .beat-favicon {
  width: 14px;
  height: 14px;
  vertical-align: -2px;
  border: none;
  border-radius: 2px;
}

/* ── Beat type navigation links ── */

.beat-type-links {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
  margin: 0.4em 0 0.8em;
}
a.beat-type-link {
  text-decoration: none;
  font-size: 0.78rem;
  padding: 3px 10px;
  top: 0;
}
a.beat-type-link:hover {
  opacity: 0.8;
}

/* ── Dark mode overrides for beats ── */

[data-theme="dark"] .beat-label.release    { background: var(--color-purple-light); color: var(--color-purple-accent); border-color: var(--color-purple-border); }
[data-theme="dark"] .beat-label.til         { background: #0d2e1c; color: #4dbb7a; border-color: #1f5c38; }
[data-theme="dark"] .beat-label.til-update      { background: #0d2e1c; color: #4dbb7a; border-color: #1f5c38; }
[data-theme="dark"] .beat-label.til-update .til-update-suffix { background: #0a2218; color: #4dbb7a; }
[data-theme="dark"] .beat-label.research        { background: #2a2000; color: #c8a830; border-color: #5a4800; }
[data-theme="dark"] .beat-label.tool            { background: #2a0a1e; color: #e060b0; border-color: #6a1a4e; }
[data-theme="dark"] .beat-label.museum          { background: #0a2622; color: #4db6ac; border-color: #1a5c52; }
[data-theme="dark"] .beat-label.sighting        { background: #102a14; color: #7cd393; border-color: #2d5b3a; }
[data-theme="dark"] .beat-label.comment         { background: #0d2236; color: #5aa8e8; border-color: #1e4a70; }
[data-theme="dark"] .comment-context            { color: #9b9b9b; }

@media (prefers-color-scheme: dark) {
  :root:not([data-theme]) .beat-label.release    { background: var(--color-purple-light); color: var(--color-purple-accent); border-color: var(--color-purple-border); }
  :root:not([data-theme]) .beat-label.til         { background: #0d2e1c; color: #4dbb7a; border-color: #1f5c38; }
  :root:not([data-theme]) .beat-label.til-update      { background: #0d2e1c; color: #4dbb7a; border-color: #1f5c38; }
  :root:not([data-theme]) .beat-label.til-update .til-update-suffix { background: #0a2218; color: #4dbb7a; }
  :root:not([data-theme]) .beat-label.research        { background: #2a2000; color: #c8a830; border-color: #5a4800; }
  :root:not([data-theme]) .beat-label.tool            { background: #2a0a1e; color: #e060b0; border-color: #6a1a4e; }
  :root:not([data-theme]) .beat-label.museum          { background: #0a2622; color: #4db6ac; border-color: #1a5c52; }
  :root:not([data-theme]) .beat-label.sighting        { background: #102a14; color: #7cd393; border-color: #2d5b3a; }
  :root:not([data-theme]) .beat-label.comment         { background: #0d2236; color: #5aa8e8; border-color: #1e4a70; }
  :root:not([data-theme]) .comment-context            { color: #9b9b9b; }
}
